<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('wallet.bonus');if(is_post()){verify_csrf();try{$uid=(int)input('user_id');$bucket=strtoupper((string)input('bucket'));$amount=trim((string)input('amount'));$expires=trim((string)input('expires_at'));if(!in_array($bucket,['BONUS','PROMO'],true)||!preg_match('/^\d{1,16}(\.\d{1,2})?$/',$amount)||decimal_compare($amount,'0.00')<=0||($expires!==''&&!strtotime($expires)))throw new InvalidArgumentException('Valid bucket, amount and expiry are required.');wallet_grant_bucket($uid,$bucket,$amount,'admin-grant:'.bin2hex(random_bytes(8)),'Administrator '.$bucket.' grant',(int)admin()['id'],idempotency_key('wallet-bonus'),$expires?str_replace('T',' ',$expires):null);flash('success','Bucket credit applied with ledger and optional expiry.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/wallet/bonus.php');}$users=db()->query("SELECT u.id,u.name,u.mobile,w.balance,w.bonus_balance,w.promo_balance,w.bonus_expires_at,w.promo_expires_at FROM users u JOIN wallets w ON w.user_id=u.id ORDER BY u.id DESC LIMIT 200")->fetchAll();$pageTitle='Bonus & promo balances';$pageSubtitle='Separate non-withdrawable bonus and temporary promo cash buckets';require APP_ROOT.'/includes/header.php';?><section class="panel"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>User</label><select name="user_id" required><?php foreach($users as $u):?><option value="<?=e($u['id'])?>">#<?=e($u['id'])?> · <?=e($u['name'])?> · <?=e($u['mobile'])?></option><?php endforeach?></select></div><div class="field"><label>Bucket</label><select name="bucket"><option>BONUS</option><option>PROMO</option></select></div><div class="field"><label>Amount</label><input name="amount" inputmode="decimal" required></div><div class="field"><label>Expiry (optional)</label><input type="datetime-local" name="expires_at"></div><div class="field full"><button class="btn">Credit bucket</button></div></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Real cash</th><th>Bonus</th><th>Promo cash</th><th>Expiry</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td>#<?=e($u['id'])?> · <?=e($u['name'])?></td><td><?=money($u['balance'])?></td><td><?=money($u['bonus_balance'])?></td><td><?=money($u['promo_balance'])?></td><td><?=e($u['bonus_expires_at']??'—')?> / <?=e($u['promo_expires_at']??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
